head.script:
scwin.condition = 0;
scwin.floatingLayer2_headerHTML = "<span> floatingLayer_2 </span>";
scwin.floatingLayer1_headerHTML = function() {
	var ret = "";
	switch (scwin.condition) {
		case 1:
			ret = "<span> test1 </span>";
			break;
		case 2:
			ret = "<span> test2 </span>";
			break;
		default:
			ret = "<span> test </span>";
			break;
	}
	return ret;
};
scwin.trigger1_onclick = function(e) {
	scwin.condition = 1;
	floatingLayer1.setHeaderHTML(scwin.floatingLayer1_headerHTML);
};
scwin.trigger2_onclick = function(e) {
	scwin.condition = 2;
	floatingLayer1.setHeaderHTML(scwin.floatingLayer1_headerHTML);
};
scwin.checktype1 = function() {
	return typeof (document.getElementById('floatingLayer1_headerHTML') || document.getElementById('mf_floatingLayer1_headerHTML')) == 'object' && (document.getElementById('floatingLayer1_headerHTML') || document.getElementById('mf_floatingLayer1_headerHTML')).innerText.trim() == 'test1';
};
scwin.checktype2 = function() {
	return typeof (document.getElementById('floatingLayer1_headerHTML') || document.getElementById('mf_floatingLayer1_headerHTML')) == 'object' && (document.getElementById('floatingLayer1_headerHTML') || document.getElementById('mf_floatingLayer1_headerHTML')).innerText.trim() == 'test2';
};
